import itertools

def calculate_F2(S, x, y):
    """Calculates F2 = F(9, 9, 9) given S = x+y+z."""
    z = S - x - y

    # Check constraints
    if not (0 <= z <= 9):
        return None

    # Calculate F2 = |x+y-18| + |y+z-18| + |z+x-18|
    F2 = abs(x + y - 18) + abs(y + z - 18) + abs(z + x - 18)
    return F2

# Dictionary to store results: {F2_value: list_of_triplets}
degeneracies = {}

# Iterate over all possible sums S (0 to 27)
for S in range(28):
    # Iterate over all possible (x, y) pairs such that z = S - x - y is also in [0, 9]
    for x in range(10):
        for y in range(10):
            # Check if the resulting triplet is valid (z is in [0, 9])
            z = S - x - y
            if 0 <= z <= 9:
                triplet = tuple(sorted((x, y, z)))
                F2_val = calculate_F2(S, x, y)

                if F2_val is not None:
                    if F2_val not in degeneracies:
                        degeneracies[F2_val] = []
                    # Store the sorted triplet to identify unique input combinations
                    degeneracies[F2_val].append(triplet)

# Identify any F2_value that maps to more than one unique triplet
degenerate_F2s = {f2: triplets for f2, triplets in degeneracies.items() if len(set(triplets)) > 1}

print(f"Total unique F2 values found: {len(degeneracies)}")
if degenerate_F2s:
    print("\n--- Degeneracy Found ---")
    for f2, triplets in degenerate_F2s.items():
        print(f"F2 = {f2} corresponds to multiple triplets: {triplets}")
else:
    print("\nNo degeneracy found. Each unique F2 value maps to a unique input triplet.")

